      oracle_text: 'As an additional cost to cast this spell, discard a card.\nDraw two cards.',
    });
    assert.ok(rolesOf(signalsFor(thrill), 'selfMill').includes('produces'));

    const windfall = makeCard({
      name: 'Windfall',
      type_line: 'Sorcery',
