    if (!hit) continue;

    // For non-counterType qualifiers, prefer the creature type actually
    // specified by the matched payoff pattern over whatever type word
    // happens to appear first in the clause — Angel of Glory's Rise is
    // the canonical example: it exiles Zombies but returns Humans, so
    // qualified must be "Human".
    if (def.qualifiable !== 'counterType') {
      const rewardsMatchers = def.roles.rewards ?? [];
      const consumedMatchers = def.roles.consumes ?? [];

      for (const matcher of rewardsMatchers) {
        if (typeof matcher !== 'function' && matcher.test(clause)) {
          const captured = matcher.exec(clause)?.[1];
          if (captured && vocab.typeByWord.has(captured.toLowerCase())) {
            return vocab.typeByWord.get(captured.toLowerCase())!;
          }
          for (const word of wordsIn(clause)) {
            const type = vocab.typeByWord.get(word);
            if (type) return type;
          }
