if (def.qualifiable !== 'counterType') {
  // A single sentence may describe a payoff AND a cost
  // ("exile all Zombies, then return all Human cards") —
  // only the type in the payoff clause's benefit matters,
  // not the cost's sacrifice/exile target.
  const splitPoint = clause.toLowerCase().lastIndexOf(', then');
  const benefit = splitPoint >= 0 ? clause.slice(splitPoint + ', then'.length).toLowerCase() : clause.toLowerCase();
  const cost = splitPoint >= 0 ? clause.slice(0, splitPoint).toLowerCase() : '';
  // Build a list of types to exclude: anything mentioned
  // in the cost portion of the sentence (what gets
  // sacrificed / exiled as the price).
  const costTypes = new Set<string>();
  for (const word of wordsIn(cost)) {
    const type = vocab.typeByWord.get(word);
    if (type) costTypes.add(type);
  }
  for (const word of wordsIn(benefit)) {
    const type = vocab.typeByWord.get(word);
    if (type && !costTypes.has(type)) return type;
  }
}

