it('Angel of Glory\'s Rise is Reanimator (Human), not (Zombie)', () => {
  // "When this creature enters, exile all Zombies, then return all Human
  // creature cards from your graveyard to the battlefield." — the payoff
  // is Humans; Zombies are merely the cost (what gets exiled). The first
  // creature-type word in the clause is "Zombies", so the old behavior
  // incorrectly returned "Zombie".
  const angelOfGlory = makeCard({
    name: 'Angel of Glory\'s Rise',
    type_line: 'Legendary Creature — Angel',
    creature_types: JSON.stringify(['Angel']),
    oracle_text:
      'Flying, vigilance\n' +
      'When this creature enters, exile all Zombies, then return all Human creature cards from your graveyard to the battlefield.',
  });
  const signals = signalsFor(angelOfGlory, ['Zombie', 'Human', 'Angel']);
  const humanQual = find(signals, 'reanimator', 'Human');
  assert.ok(humanQual, 'expected a Human-qualified reanimator signal');
  assert.strictEqual(humanQual.label, 'Reanimator (Human)');
  assert.strictEqual(find(signals, 'reanimator', 'Zombie'), undefined, 'must NOT produce Zombie-qualified reanimator');
  assert.strictEqual(find(signals, 'reanimator', undefined), undefined, 'must NOT produce generic reanimator');
  assert.ok(find(signals, 'kindred', 'Human'), 'must qualify as Human kindred');
  assert.strictEqual(find(signals, 'kindred', 'Zombie'), undefined, 'must NOT qualify as Zombie kindred');
});

it('an unrestricted reanimator stays unqualified', () => {
  const generic = makeCard({
    name: 'Generic Necromancer',
    type_line: 'Legendary Creature — Human Wizard',
    oracle_text: 'Return target creature card from your graveyard to the battlefield.',
  });
  const signals = signalsFor(generic, ['Sliver']);
  assert.ok(find(signals, 'reanimator', undefined), 'expected an unqualified reanimator signal');
});

