function findQualifier(facts: CardFacts, def: ArchetypeDef, vocab: Vocabulary): string | undefined {
  // Counters' qualifying evidence usually lives in the PRODUCES clause
  // itself ("enters with three +1/+1 counters" has no separate payoff
  // clause to restrict from), not just rewards/consumes — so every clause
  // is a candidate, and findCounterKind is precise enough on its own not to
  // need pre-filtering by which role matched.
  if (def.qualifiable === 'counterType') {
    for (const clause of clauses(facts.text)) {
      const kind = findCounterKind(clause);
      if (kind) return kind;
    }
    return undefined;
  }

  const payoffMatchers = [...(def.roles.rewards ?? []), ...(def.roles.consumes ?? [])];
  for (const clause of clauses(facts.text)) {
    let hit = payoffMatchers.some((m) => (typeof m === 'function' ? false : m.test(clause)));
    if (!hit) continue;

    // A single sentence may describe a payoff AND a cost
    // ("exile all Zombies, then return all Human cards") —
    // only the type in the payoff clause's benefit matters,
    // not the cost's sacrifice/exile target.
    const splitPoint = clause.toLowerCase().lastIndexOf(', then');
    const benefit = splitPoint >= 0 ? clause.slice(splitPoint + ', then'.length).toLowerCase() : clause.toLowerCase();
    const cost = splitPoint >= 0 ? clause.slice(0, splitPoint).toLowerCase() : '';
    // Build a list of types to exclude: anything mentioned
    // in the cost portion of the sentence (what gets
    // sacrificed / exiled as the price).
    const costTypes = new Set<string>();
    for (const word of wordsIn(cost)) {
      const type = vocab.typeByWord.get(word);
      if (type) costTypes.add(type);
    }
    for (const word of wordsIn(benefit)) {
      const type = vocab.typeByWord.get(word);
      if (type && !costTypes.has(type)) return type;
    }

    for (const word of wordsIn(clause)) {
      const type = vocab.typeByWord.get(word);
      if (type) return type;
    }
  }
  return undefined;
}

function rolesFor(def: ArchetypeDef, facts: CardFacts, vocab: Vocabulary): Role[] {
  const found: Role[] = [];
  for (const role of ROLES) {
    const matchers = def.roles[role];
    if (matchers?.some((m) => matches(m, facts, vocab))) found.push(role);
  }
  return found;
}

